if (!root) return;

if (item < root->data) {
    avlDelete(root->left, item);
} else if (item > root->data) {
    avlDelete(root->right, item);
} else {
    if (!root->left && !root->right) {
        delete root;
        root = nullptr;
    } else if (!root->left) {
        TreeNode<T>* temp = root;
        root = root->right;
        delete temp;
    } else if (!root->right) {
        TreeNode<T>* temp = root;
        root = root->left;
        delete temp;
    } else {
        TreeNode<T>* successor = bstFindMin(root->right);
        root->data = successor->data;
        avlDelete(root->right, successor->data);
    }
}

if (!root) return;

root->height = 1 + std::max(bstHeight(root->left), bstHeight(root->right));

int balance = bstHeight(root->left) - bstHeight(root->right);

if (balance > 1) {
    if (bstHeight(root->left->left) >= bstHeight(root->left->right)) {
        avlRotateLeft(root);
    } else {
        avlRotateRight(root->left);
        avlRotateLeft(root);
    }
} else if (balance < -1) {
    if (bstHeight(root->right->right) >= bstHeight(root->right->left)) {
        avlRotateRight(root);
    } else {
        avlRotateLeft(root->right);
        avlRotateRight(root);
    }
}

